export async function resolveRouting(courses,{signal,fetcher}){try{const routes=await fetcher(courses,{signal});const count=[...routes.values()].filter(value=>Object.keys(value).length>0).length;return {routes,state:count===0?'unavailable':count<courses.length?'partial':'success',count,message:count===0?'도로 경로 없음':`도로 ${count}/${courses.length}곳 조회`};}catch(error){return {routes:new Map(),state:error.name==='AbortError'?'timeout':'failed',count:0,message:error.name==='AbortError'?'도로 조회 시간초과':`도로 조회 실패: ${error.message}`};}}
export function analysisNotice({count,limit,sortLabel,routing}){const reason=routing?.message||'도로 미조회 · ANALYSIS 버튼으로 조회';return {text:`분석 ${count}개 → 최대 ${limit}곳 · 정렬: ${sortLabel} · ${reason}`,error:['timeout','failed','unavailable'].includes(routing?.state)};}
